function check([nums, k], actual, expected) {
  if (!Array.isArray(actual) || actual.length !== k) return false;
  // actual must be a subsequence of nums: match its elements left to right.
  let j = 0;
  for (let i = 0; i < nums.length && j < actual.length; i++) {
    if (nums[i] === actual[j]) j++;
  }
  if (j !== actual.length) return false;
  const total = list => list.reduce((sum, v) => sum + v, 0);
  return total(actual) === total(expected);
}

