function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -100000 || v > 100000)) return 'Each value is an integer between -10^5 and 10^5.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is between 1 and the length of nums.';
  return null;
}

