function maxSubsequence(nums, k) {
  const order = [];
  for (let i = 0; i < nums.length; i++) {
    order.push(i);
  }
  order.sort((a, b) => nums[b] - nums[a]);

  const chosen = order.slice(0, k);
  chosen.sort((a, b) => a - b);

  const result = [];
  for (const index of chosen) {
    result.push(nums[index]);
  }
  return result;
}

