function maxSubsequence(nums, k) {
  // Drop the smallest remaining element until only k are left; the order of the rest never changes.
  const rest = nums.slice();
  while (rest.length > k) {
    let smallest = 0;
    for (let i = 1; i < rest.length; i++) if (rest[i] < rest[smallest]) smallest = i;
    rest.splice(smallest, 1);
  }
  return rest;
}

