function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 8);
  const span = size === 'large' ? (rand() < 0.5 ? 100000 : 50) : 1 + Math.floor(rand() * 6);
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  const k = 1 + Math.floor(rand() * n);
  return [nums, k];
}
